// 全局唯一出口
@RestControllerAdvice
public class GlobalExceptionHandler {
  @ExceptionHandler(BizException.class)
  public ApiResponse<Void> handle(BizException e) { return ApiResponse.fail(e.getCode(), e.getMessage()); }
}

public ApiResponse<PageResult<UserVO>> list(@RequestParam(defaultValue = "10") @Min(1) @Max(200) int pageSize)

// 或统一在 PageQuery 基类里夹逼
public abstract class PageQuery {
  private static final int MAX_SIZE = 200;
  public int safeSize() { return Math.min(Math.max(size, 1), MAX_SIZE); }
}
